  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Church and Faith Vocabulary$j$, $j${"readings": [{"title": "Psalm 23 (King James Version)", "url": "/portal/bible/Psalms/23"}], "body": "Psalm 23:1 says, The LORD is my shepherd; I shall not want. Many Spanish speaking neighbors in Florida worship in Spanish, and knowing the language of faith helps you pray with them, welcome them and serve them. In this course all Scripture quotations are in the King James Version. Spanish speaking churches often use Spanish translations of the Bible, and the vocabulary below will help you recognize the words they use.\n\nKey words include Dios for God, Jesús or Jesucristo for Jesus Christ, el Señor for the Lord, el Espíritu Santo for the Holy Ghost, la Biblia for the Bible, el evangelio for the gospel, la fe for faith, la esperanza for hope, el amor for love, la gracia for grace, la oración for prayer, la alabanza for praise, la adoración for worship, el pecado for sin, el perdón for forgiveness, la salvación for salvation, el bautismo for baptism, el cielo for heaven and la vida for life.\n\nPeople and places include la iglesia for church, el templo for sanctuary, el pastor and la pastora, el obispo for bishop, el apóstol for apostle, el hermano and la hermana for brother and sister in Christ, el culto for worship service, el coro for choir, el domingo for Sunday and el estudio bíblico for Bible study.\n\nVerbs include orar for to pray, cantar for to sing, leer for to read, adorar for to worship, servir for to serve, creer for to believe, bendecir for to bless and ayudar for to help. Common phrases are Dios te bendiga or Que Dios te bendiga for God bless you, Gloria a Dios for glory to God, Amén for so be it, Aleluya for praise the LORD, Dios es amor for God is love, Paz de Dios for peace of God and Vamos a orar for let us pray. First John 4:8 says, God is love.\n\nYour task: (1) Write ten faith words in Spanish. (2) Write five Spanish sentences about prayer, church or the Bible.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Psalm 23:1 says, The LORD is my shepherd; I shall not want. In this course, all Scripture quotations are in the King James Version. The Spanish words today help you recognize what Spanish speaking churches say.\n\nNow watch this. Dios is God. Jesucristo is Jesus Christ. El Señor is the Lord. El Espíritu Santo is the Holy Ghost. La Biblia, la fe, la esperanza, el amor, la gracia, la oración, la alabanza, el perdón, la salvación.\n\nLa iglesia, el pastor, la pastora, el culto, el coro. Verbs are orar, cantar, adorar, servir, creer, bendecir.\n\nQue Dios te bendiga means God bless you. Gloria a Dios. Amén. Aleluya. Dios es amor. Vamos a orar means let us pray.\n\nYour task is to write ten faith words and five sentences. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Church and Faith Vocabulary$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Future Plans and Careers$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established. Making plans with prayer and wisdom is part of a faithful life, and Spanish gives us several ways to talk about the future.\n\nThe most common way is ir a plus an infinitive. Voy a estudiar means I am going to study. Vas a trabajar means you are going to work. Ella va a viajar means she is going to travel. Vamos a orar means we are going to pray. The verb pensar, which means to think or to plan, changes e to ie: pienso, piensas, piensa, pensamos, piensan. Pienso estudiar medicina means I plan to study medicine. Querer and esperar, which means to hope, are also followed by infinitives: Quiero ser maestro. Espero servir a Dios.\n\nFuture time words include mañana for tomorrow, esta noche for tonight, la próxima semana for next week, el próximo mes for next month, el próximo año for next year, pronto for soon and algún día for someday.\n\nCareers and callings include el médico or la médica for doctor, el maestro or la maestra for teacher, la enfermera for nurse, el ingeniero for engineer, el abogado for lawyer, el pastor for pastor, el misionero for missionary, el cocinero for cook, el programador for programmer, el intérprete for interpreter, el contador for accountant, el policía for police officer and el empresario for business owner. Use ser without an article for occupations: Mi padre es maestro. To say what you want to be, use Quiero ser or Voy a ser.\n\nYour task: (1) Conjugate ir a plus an infinitive for all subjects with the verb estudiar. (2) Write five sentences about your plans. (3) Name three careers where Spanish would help you serve people.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Proverbs 16:3 says, Commit thy works unto the LORD, and thy thoughts shall be established.\n\nNow watch this. The easiest future is ir a plus an infinitive. Voy a estudiar. Vas a trabajar. Ella va a viajar. Vamos a orar. Pensar means to plan. Pienso, piensas, piensa, pensamos, piensan. Pienso estudiar medicina.\n\nTime words are mañana, esta noche, la próxima semana, el próximo año, pronto and algún día.\n\nCareers are el médico, el maestro, la enfermera, el ingeniero, el abogado, el pastor, el misionero, el intérprete and el programador. For jobs, we use ser without an article. Mi padre es maestro. Quiero ser enfermera.\n\nYour task is to conjugate ir a estudiar, write five sentences about your plans and name three careers. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Future Plans and Careers$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Talking About the Past: An Introduction to the Preterite$j$, $j${"readings": [{"title": "Psalm 77 (King James Version)", "url": "/portal/bible/Psalms/77"}], "body": "Psalm 77:11 says, I will remember the works of the LORD: surely I will remember thy wonders of old. Telling what happened in the past is a way to give testimony, and Spanish uses the preterite tense for completed actions.\n\nFor regular ar verbs, drop ar and add é, aste, ó, amos and aron. Hablar becomes hablé, hablaste, habló, hablamos, hablaron. Ayer hablé con mi pastor means yesterday I spoke with my pastor. For regular er and ir verbs, drop the ending and add í, iste, ió, imos and ieron. Comer becomes comí, comiste, comió, comimos, comieron. Vivir becomes viví, viviste, vivió, vivimos, vivieron. Notice the accent marks on the yo and the él, ella and usted forms. The nosotros form of ar and ir verbs looks the same in the present and the preterite, so context tells the meaning.\n\nTwo very common verbs are irregular and share the same forms in the preterite: ser and ir are fui, fuiste, fue, fuimos, fueron. Fui a la iglesia means I went to church. Fue un buen día means it was a good day. Other useful irregular verbs include hacer, with hice, hiciste, hizo, hicimos and hicieron, and tener, with tuve, tuviste, tuvo, tuvimos and tuvieron.\n\nPast time words include ayer for yesterday, anoche for last night, anteayer for the day before yesterday, la semana pasada for last week, el mes pasado for last month, el año pasado for last year and hace dos días for two days ago.\n\nYour task: (1) Conjugate cantar and escribir in the preterite. (2) Write five sentences telling what you did last weekend.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Psalm 77:11 says, I will remember the works of the LORD: surely I will remember thy wonders of old. Telling what happened is a way to give testimony.\n\nNow watch this. The preterite tells what happened. For ar verbs, add é, aste, ó, amos, aron. Hablé, hablaste, habló, hablamos, hablaron. For er and ir verbs, add í, iste, ió, imos, ieron. Comí, comiste, comió, comimos, comieron.\n\nSer and ir share the same forms. Fui, fuiste, fue, fuimos, fueron. Fui a la iglesia. Hacer is hice, hiciste, hizo, hicimos, hicieron.\n\nPast time words are ayer, anoche, la semana pasada, el mes pasado, el año pasado and hace dos días.\n\nYour task is to conjugate cantar and escribir and write five sentences about last weekend. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Talking About the Past: An Introduction to the Preterite$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Serving Neighbors, Careers and Next Steps$j$, $j${"readings": [{"title": "Matthew 28 (King James Version)", "url": "/portal/bible/Matthew/28"}], "body": "Matthew 28:19 says, Go ye therefore, and teach all nations. Matthew 25:35 says, I was a stranger, and ye took me in. A language is a tool for love, and Spanish can open doors to serve neighbors, share the gospel and work with excellence.\n\nWays to use Spanish in service include welcoming visitors at church with Bienvenidos and ¿En qué puedo ayudarle?, which means how can I help you; helping with children's ministry or tutoring; reading to others; helping a family with forms or directions; and serving in community outreach and food ministry. Always speak with respect, use usted with elders, listen carefully, ask if you do not understand and never pretend to know more than you do. In important situations, such as legal, medical or financial matters, bring in a trained interpreter and do not guess. Be honest about your level. Say Estoy aprendiendo español, which means I am learning Spanish, and Hable más despacio, por favor, which means speak more slowly, please.\n\nCareers that use Spanish include medicine and nursing, teaching, social work, law enforcement, business, customer service, ministry and missions, translation and interpretation, journalism and technology. Many jobs in Florida pay more or open more doors to people who can speak Spanish.\n\nTo continue learning, practice a little every day, read short texts in Spanish, listen to Spanish music and sermons, speak with a native speaker you trust with an adult nearby, keep a vocabulary notebook and study the next course, Spanish 2. Learning a language is a journey of years, and every day counts.\n\nYour task: (1) Write a one minute self introduction in Spanish using what you learned in this course. (2) Write three ways you will use Spanish to serve others.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Matthew 28:19 says, Go ye therefore, and teach all nations. Matthew 25:35 says, I was a stranger, and ye took me in. A language is a tool for love.\n\nNow watch this. You can welcome visitors with Bienvenidos and ¿En qué puedo ayudarle? You can help with children, tutoring, outreach and food ministry. Speak with respect. Use usted with elders. Ask when you do not understand. Be honest about your level. Say estoy aprendiendo español. Say hable más despacio, por favor. In legal, medical or financial matters, bring in a trained interpreter and do not guess.\n\nCareers that use Spanish include medicine, nursing, teaching, social work, business, ministry, interpretation and technology.\n\nTo keep learning, practice a little every day, read short Spanish texts, listen to Spanish music and sermons, keep a vocabulary notebook and continue to Spanish 2.\n\nYour task is to write a one minute self introduction and three ways to serve. Take the four question check, then the unit quiz. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Serving Neighbors, Careers and Next Steps$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Faith, Future Plans, the Past Tense and Serving Others$j$, $j${"prompt": "Write a report of at least 250 words in English with Spanish examples. Use complete sentences and label each part. Matthew 28:19 says, Go ye therefore, and teach all nations.\n\nPart 1: Write twelve faith and church words in Spanish with meanings and five phrases a Spanish speaking Christian might say. Explain why this course quotes Scripture in the King James Version.\nPart 2: Write six sentences in Spanish about your future plans using ir a, pensar and querer, and name three careers where Spanish helps people.\nPart 3: Conjugate hablar, comer and ir in the preterite, and write six sentences in Spanish about what you did last weekend.\nPart 4: Explain three ways a student can use Spanish to serve others honestly and respectfully, and when to bring in a trained interpreter.\nPart 5: Explain how Matthew 28:19, Matthew 25:35 and Psalm 77:11 guide you in using a language to bless people and to give testimony.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Faith, Future Plans, the Past Tense and Serving Others$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Go Ye Therefore, and Teach All Nations$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes one way you hope to use Spanish to serve your church, school or community, (2) uses at least five Spanish words or sentences from this unit, including at least one in the past tense and one about the future, (3) explains why honesty about your skill level matters when you serve, and (4) connects your answer to Matthew 28:19, Matthew 25:35 or Psalm 77:11. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can learning a language be an act of love? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Go Ye Therefore, and Teach All Nations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Church and Faith Vocabulary$j$, $j${"questions": [{"q": "La oración means:", "options": ["Sin", "Church", "Prayer", "Praise"]}, {"q": "Que Dios te bendiga means:", "options": ["God is great", "Go to church", "God bless you", "Thank God"]}, {"q": "El culto is:", "options": ["The Bible", "The choir", "The worship service", "The pastor"]}, {"q": "Dios es amor means:", "options": ["God is good", "God is here", "God is love", "God is king"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Church and Faith Vocabulary$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,2}'::int[], array[$j$Oración is prayer.$j$,$j$Bendecir means to bless.$j$,$j$Culto is a worship service.$j$,$j$Amor is love.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Church and Faith Vocabulary$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Future Plans and Careers$j$, $j${"questions": [{"q": "Voy a estudiar means:", "options": ["I want to study", "I am going to study", "I studied", "I study every day"]}, {"q": "Pienso estudiar medicina means:", "options": ["I think about medicine", "I plan to study medicine", "I studied medicine", "I like medicine"]}, {"q": "El próximo año means:", "options": ["Every year", "This year", "Last year", "Next year"]}, {"q": "Mi padre es maestro. Why is there no un before maestro?", "options": ["Ser needs two nouns", "It is a mistake", "Occupations after ser usually omit the article", "Maestro is feminine"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Future Plans and Careers$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,2}'::int[], array[$j$Ir a plus an infinitive expresses the near future.$j$,$j$Pensar plus an infinitive means to plan to.$j$,$j$Próximo means next.$j$,$j$After ser, an occupation is used without un or una unless it is described.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Future Plans and Careers$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Talking About the Past: An Introduction to the Preterite$j$, $j${"questions": [{"q": "The yo form of hablar in the preterite is:", "options": ["Hablé", "Hablo", "Hablaré", "Hablaba"]}, {"q": "Ellos comieron means:", "options": ["We ate", "They eat", "They ate", "They will eat"]}, {"q": "Fui a la iglesia means:", "options": ["I go to church", "I was a church", "He went to church", "I went to church"]}, {"q": "Anoche means:", "options": ["Last night", "This morning", "Tomorrow", "Next week"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Talking About the Past: An Introduction to the Preterite$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,0}'::int[], array[$j$Ar verbs take é in the yo form.$j$,$j$Ieron is the ellos ending for er verbs.$j$,$j$Fui is the yo form of ir in the preterite.$j$,$j$Anoche is last night.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Talking About the Past: An Introduction to the Preterite$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Serving Neighbors, Careers and Next Steps$j$, $j${"questions": [{"q": "Estoy aprendiendo español means:", "options": ["I speak Spanish well", "I am from Spain", "I teach Spanish", "I am learning Spanish"]}, {"q": "In a legal or medical situation, you should:", "options": ["Bring in a trained interpreter", "Avoid the person", "Guess the words", "Use a translation app only"]}, {"q": "Hable más despacio, por favor means:", "options": ["Speak more slowly, please", "Come here, please", "Sit down, please", "Speak louder, please"]}, {"q": "¿En qué puedo ayudarle? means:", "options": ["How can I help you?", "What time is it?", "Do you need money?", "Where are you from?"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Serving Neighbors, Careers and Next Steps$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,0,0}'::int[], array[$j$Aprendiendo means learning.$j$,$j$Accuracy matters in serious matters.$j$,$j$Despacio means slowly.$j$,$j$Ayudarle means to help you formally.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Serving Neighbors, Careers and Next Steps$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Faith, Future Plans, the Past Tense and Serving Others$j$, $j${"questions": [{"q": "La esperanza means:", "options": ["Love", "Hope", "Grace", "Faith"]}, {"q": "Vamos a orar means:", "options": ["We prayed", "We want to pray", "We pray often", "Let us pray"]}, {"q": "Ella va a viajar means:", "options": ["She wants a trip", "She travels often", "She traveled", "She is going to travel"]}, {"q": "Quiero ser enfermera means:", "options": ["I want to be a nurse", "I need a nurse", "I was a nurse", "I am a nurse"]}, {"q": "The preterite nosotros form of hablar is:", "options": ["Hablábamos", "Hablaron", "Hablemos", "Hablamos"]}, {"q": "Ayer comí arroz means:", "options": ["I like rice", "I eat rice daily", "Tomorrow I will eat rice", "Yesterday I ate rice"]}, {"q": "Fuimos al parque means:", "options": ["We went to the park", "We are going to the park", "We are in the park", "We like the park"]}, {"q": "When should you bring in a trained interpreter?", "options": ["Only for greetings", "Never", "In legal, medical or financial matters", "Only at church picnics"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Faith, Future Plans, the Past Tense and Serving Others$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,3,0,3,3,0,2}'::int[], array[$j$Esperanza is hope.$j$,$j$Ir a plus an infinitive can invite.$j$,$j$Va a plus an infinitive is the near future.$j$,$j$Quiero ser means I want to be.$j$,$j$Ar verbs have the same nosotros form in present and preterite.$j$,$j$Comí is the yo preterite form.$j$,$j$Fuimos is from ir.$j$,$j$Accuracy matters when decisions are serious.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Faith, Future Plans, the Past Tense and Serving Others$j$ on conflict (item_id) do nothing;
